// <auto-generated/>
using Fanex.CustomerSetting.Module.Core.Criteria;
using Fanex.CustomerSetting.Module.Core.Services.Impl;
using Fanex.Tarus.Security.Criteria;
using Sunplus.Accounting.Business;
using Sunplus.Accounting.Business.Security;
using Sunplus.Accounting.Core.Common;
using Sunplus.Accounting.Core.Configurations;
using System;
using System.Configuration;

public partial class InternalView : System.Web.UI.Page
{
    private enum AlphaSiteCode
    {
        I1 = 1,
        I7 = 7,
        I9 = 9,
        I8 = 8
    }

    protected void Page_Load(object sender, EventArgs e)
    {
        var serviceBase = new ServiceBase();
        string strParams = Request["custName"] + "&" + Request["accId"] + "&" + Sunplus.Accounting.DataAccess.IBCDLL.SystemInfo.GetDBTime().Ticks;
        string strPath = Request.PhysicalApplicationPath + "/IbcKeys/ibcpkey.snk";
        bool isDummyAcc = Permissions.CheckDummyAccount(new CheckDummyAccountCriteria() { CustName = Request["custName"] });
        var checkCustomerBelongToSpecialSiteResult = serviceBase.CheckCustomerBelongToSpecialSite(new CheckCustomerIsSpecialSiteCriteria() { UserName = Request["custName"] });

        if (isDummyAcc || checkCustomerBelongToSpecialSiteResult.IsSpecialHeadline)
        {
            if (!Permissions.HasPermission(Enumerations.Functions.AccessSpecialSites))
            {
                Response.Write(GetGlobalResourceObject(Constants.Resources.LanguageResources, "DontHavePermission"));
                return;
            }
        }
        else
        {
            var checkSpecialSitePermission = serviceBase.CheckSpecialSitePermission(
                       new CheckSpecialSitePermissionCriteria()
                       {
                           UserID = Convert.ToInt32(Request["accId"]),
                           CustName = Request["custName"]
                       });
            if (checkSpecialSitePermission.ErrorCode > 0)
            {
                Response.Write(GetGlobalResourceObject(Constants.Resources.LanguageResources, "DontHavePermission"));
                return;
            }
        }

        strParams = AccountingCoreUtils.EncryptString(strParams, 1024, strPath);

        string internalAgentUrl = GetInternalLoginUrl((AlphaSiteCode)checkCustomerBelongToSpecialSiteResult.SiteCode);
        string url = string.Format("{0}?{1}params={2}&isVpn={3}",
            (internalAgentUrl.StartsWith("http") ? internalAgentUrl : "http://" + internalAgentUrl),
            Session[WebSettings.InternalAgentUMToken] == null ? "" : string.Format("UMToken={0}&", Session[WebSettings.InternalAgentUMToken]),
            strParams,
            IsLocalOrVpnRequest(Request.Headers["Host"]));

        Response.Redirect(url);
        Response.End();
    }

    private static int IsLocalOrVpnRequest(string ip)
    {
        var ipReturn = string.IsNullOrWhiteSpace(ip) ? string.Empty : ip;
        return ipReturn.Split('.').Length == 4 &&
            (ipReturn.StartsWith("10.", StringComparison.OrdinalIgnoreCase) ||
            ipReturn.StartsWith("172.16.", StringComparison.OrdinalIgnoreCase) ||
            ipReturn.StartsWith("192.168.", StringComparison.OrdinalIgnoreCase)) ? 1 : 0;
    }

    private static string GetInternalLoginUrl(AlphaSiteCode siteCode)
    {
        switch (siteCode)
        {
            case AlphaSiteCode.I7:
                return ConfigurationManager.AppSettings["int_agent_url7"];
            case AlphaSiteCode.I9:
                return ConfigurationManager.AppSettings["int_agent_url9"];
            case AlphaSiteCode.I8:
                return ConfigurationManager.AppSettings["int_agent_url8"];
            default:
                return ConfigurationManager.AppSettings["int_agent_url"];
        }
    }
}